import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';


export type FuturisticPillarsProps = Record<string, any>;

const FuturisticPillars: React.FC<FuturisticPillarsProps> = ({
  backgroundColor = "#020617", // Deep Dark Blue Void
  transparentBackground = false,
  durationInSeconds = 10,
  pillarCount = 2, // Default to two tall pillars
  pillarColor = "#0f172a", // Deep Navy Blue
  glowColor = "#06b6d4", // Electric Cyan
  motionType = "rising",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const totalFrames = durationInSeconds * fps;

  // Background Logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Smooth slow camera movement (Cinematic Scale and Pan)
  const cameraScale = interpolate(frame, [0, totalFrames], [1, 1.15]);
  const cameraPanY = interpolate(frame, [0, totalFrames], [0, height * 0.05]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden", perspective: "1200px" }}>
      <AbsoluteFill
        style={{
          transform: `scale(${cameraScale}) translateY(${cameraPanY}px)`,
          justifyContent: "center",
          alignItems: "center",
          flexDirection: "row",
          gap: `${width * 0.08}px`,
          transition: "none",
        }}
      >
        {Array.from({ length: pillarCount }).map((_, index) => {
          // Staggered cinematic timing
          const staggerDelay = index * 25;
          
          // Using a heavy spring for smooth cinematic motion
          const motionProgress = spring({
            frame: Math.max(0, frame - staggerDelay),
            fps,
            config: { damping: 120, mass: 5, stiffness: 30 },
            durationInFrames: totalFrames * 0.4,
          });

          // Compute transformations based on motion type
          let translateY = 0;
          let rotateY = 0;
          let rotateX = 0;
          
          const breathingEffect = Math.sin((frame + staggerDelay) / 40) * 15;

          if (motionType === "rising") {
            translateY = interpolate(motionProgress, [0, 1], [height * 1.5, 0]) + breathingEffect;
          } else if (motionType === "descending") {
            translateY = interpolate(motionProgress, [0, 1], [-height * 1.5, 0]) + breathingEffect;
          } else if (motionType === "rotating") {
            translateY = interpolate(motionProgress, [0, 1], [height * 0.8, 0]) + breathingEffect;
            rotateY = interpolate(frame, [0, totalFrames], [0, 180]);
            rotateX = interpolate(motionProgress, [0, 1], [60, 0]);
          }

          const pillarWidth = Math.min((width * 0.7) / pillarCount, 250);
          
          // High-tech abstract grid pattern for the pillars
          const sciFiGrid = `repeating-linear-gradient(0deg, transparent, transparent ${height * 0.05}px, ${glowColor}22 ${height * 0.05}px, ${glowColor}44 ${height * 0.052}px)`;

          return (
            <div
              key={index}
              style={{
                width: `${pillarWidth}px`,
                height: `${height * 1.4}px`, // Extremely tall for the rising/descending bounds
                backgroundColor: pillarColor,
                border: `2px solid ${glowColor}`,
                boxShadow: `0 0 40px ${glowColor}60, inset 0 0 30px ${glowColor}40`,
                borderRadius: "12px",
                transform: `translateY(${translateY}px) rotateX(${rotateX}deg) rotateY(${rotateY}deg)`,
                transformStyle: "preserve-3d",
                backgroundImage: sciFiGrid,
                transition: "none",
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                position: "relative",
              }}
            >
              {/* Core glow line within the pillar */}
              <div
                style={{
                  width: "4px",
                  height: "100%",
                  backgroundColor: glowColor,
                  boxShadow: `0 0 20px ${glowColor}, 0 0 40px ${glowColor}`,
                  opacity: interpolate(Math.sin((frame + staggerDelay * 2) / 20), [-1, 1], [0.3, 1]),
                  transition: "none",
                }}
              />
            </div>
          );
        })}
      </AbsoluteFill>

      {/* Cinematic Dark Void - Top Gradient */}
      <AbsoluteFill
        style={{
          background: `linear-gradient(180deg, ${backgroundColor} 0%, ${backgroundColor}FA 10%, transparent 40%)`,
          pointerEvents: "none",
          transition: "none",
        }}
      />

      {/* Cinematic Dark Void - Bottom Gradient */}
      <AbsoluteFill
        style={{
          background: `linear-gradient(0deg, ${backgroundColor} 0%, ${backgroundColor}FA 15%, transparent 50%)`,
          pointerEvents: "none",
          transition: "none",
        }}
      />
    </AbsoluteFill>
  );
};

export default FuturisticPillars;